interface Ringable{String ring();}class AlarmClock implements Ringable{String time;AlarmClock(String t){time=t;}public String ring(){return "Alarm ringing for "+time;}}class Doorbell implements Ringable{String location;Doorbell(String l){location=l;}public String ring(){return "Doorbell ringing at "+location;}}public class Main{static void ringAll(Ringable[] d){for(Ringable x:d)System.out.println(x.ring());}public static void main(String[]a){ringAll(new Ringable[]{new AlarmClock("7:00 AM"),new Doorbell("Front Door")});}}